import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

public class Solution {
    record Item(String nome, BigDecimal preco, int quantidade) {}

    interface Desconto {
        BigDecimal aplicar(BigDecimal subtotal);
    }

    static class SemDesconto implements Desconto {
        public BigDecimal aplicar(BigDecimal subtotal) { return subtotal; }
    }

    static class DescontoClienteNovo implements Desconto {
        public BigDecimal aplicar(BigDecimal subtotal) {
            return subtotal.multiply(new BigDecimal("0.90"));
        }
    }

    static class DescontoVip implements Desconto {
        public BigDecimal aplicar(BigDecimal subtotal) {
            return subtotal.multiply(new BigDecimal("0.80"));
        }
    }

    static class DescontoFuncionario implements Desconto {
        public BigDecimal aplicar(BigDecimal subtotal) {
            return subtotal.multiply(new BigDecimal("0.70"));
        }
    }

    static class CalculadoraPreco {
        private Desconto desconto;

        CalculadoraPreco(Desconto desconto) {
            trocarDesconto(desconto);
        }

        void trocarDesconto(Desconto desconto) {
            if (desconto == null) throw new IllegalArgumentException("desconto obrigatorio");
            this.desconto = desconto;
        }

        BigDecimal total(List<Item> itens) {
            if (itens == null || itens.isEmpty()) return BigDecimal.ZERO.setScale(2);
            BigDecimal subtotal = BigDecimal.ZERO;
            for (var item : itens) {
                if (item.preco() == null || item.preco().signum() < 0) {
                    throw new IllegalArgumentException("preco invalido");
                }
                if (item.quantidade() <= 0) {
                    throw new IllegalArgumentException("quantidade invalida");
                }
                subtotal = subtotal.add(item.preco().multiply(BigDecimal.valueOf(item.quantidade())));
            }
            return desconto.aplicar(subtotal).setScale(2, RoundingMode.HALF_UP);
        }
    }
}

