import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.math.BigDecimal;
import java.util.List;

class SolutionTest {
    private final List<Solution.Item> itens = List.of(
        new Solution.Item("A", new BigDecimal("100.00"), 2),
        new Solution.Item("B", new BigDecimal("50.00"), 1));

    @Test void semDesconto() {
        var c = new Solution.CalculadoraPreco(new Solution.SemDesconto());
        assertEquals(new BigDecimal("250.00"), c.total(itens));
    }

    @Test void cadaEstrategiaAplicaSeuPercentual() {
        assertEquals(new BigDecimal("225.00"),
            new Solution.CalculadoraPreco(new Solution.DescontoClienteNovo()).total(itens));
        assertEquals(new BigDecimal("200.00"),
            new Solution.CalculadoraPreco(new Solution.DescontoVip()).total(itens));
        assertEquals(new BigDecimal("175.00"),
            new Solution.CalculadoraPreco(new Solution.DescontoFuncionario()).total(itens));
    }

    @Test void trocaDeEstrategiaEmRuntime() {
        var c = new Solution.CalculadoraPreco(new Solution.SemDesconto());
        assertEquals(new BigDecimal("250.00"), c.total(itens));
        c.trocarDesconto(new Solution.DescontoVip());
        assertEquals(new BigDecimal("200.00"), c.total(itens));
    }

    @Test void listaVazia() {
        var c = new Solution.CalculadoraPreco(new Solution.DescontoVip());
        assertEquals(new BigDecimal("0.00"), c.total(List.of()));
        assertEquals(new BigDecimal("0.00"), c.total(null));
    }

    @Test void itemInvalidoFalha() {
        var c = new Solution.CalculadoraPreco(new Solution.SemDesconto());
        assertThrows(IllegalArgumentException.class, () -> c.total(List.of(
            new Solution.Item("X", new BigDecimal("-1"), 1))));
        assertThrows(IllegalArgumentException.class, () -> c.total(List.of(
            new Solution.Item("X", new BigDecimal("10"), 0))));
    }

    @Test void arredondamentoHalfUp() {
        var c = new Solution.CalculadoraPreco(new Solution.DescontoVip());
        var total = c.total(List.of(new Solution.Item("X", new BigDecimal("0.03"), 1)));
        assertEquals(new BigDecimal("0.02"), total);
    }
}
